let deadline = tokio::time::Instant::now() + budget;   // once, at ingress
let token = CancellationToken::new();                // child_token() propagates

tokio::select! {
    _ = token.cancelled() => Err(DeadlineExceeded),  // caller gave up
    r = tokio::time::timeout_at(deadline, call_downstream(req)) => {
        r.map_err(|_| DeadlineExceeded)?
    }
}
